import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'
import type { SolverResult } from '@/registry/calculator/lib/solver/protocol'

export type Relation = {
  id: string
  source: string
  ast: RelationAst
  createdAt: number
  enabled: boolean
}

export type SolverState =
  | { phase: 'idle' }
  | { phase: 'diagnostic'; code: 'no-relations'; message: string }
  | { phase: 'loading'; requestId: string }
  | { phase: 'complete'; requestId: string; result: SolverResult }

export type CalculatorState = {
  source: string
  relations: Relation[]
  editingId: string | null
  solver: SolverState
  helpOpen: boolean
}

export const initialCalculatorState: CalculatorState = {
  source: '',
  relations: [],
  editingId: null,
  solver: { phase: 'idle' },
  helpOpen: false,
}

export type CalculatorAction =
  | { type: 'source-changed'; source: string }
  | {
      type: 'save'
      id: string
      source: string
      ast: RelationAst
      now: number
    }
  | { type: 'edit'; id: string }
  | { type: 'delete'; id: string }
  | { type: 'enabled-changed'; id: string; enabled: boolean }
  | { type: 'clear-editor' }
  | { type: 'clear-all' }
  | { type: 'help-changed'; open: boolean }
  | {
      type: 'local-diagnostic'
      code: 'no-relations'
      message: string
    }
  | { type: 'solve-started'; requestId: string }
  | {
      type: 'solve-finished'
      requestId: string
      result: SolverResult
    }

export type OperationItem = {
  id: string
  label: string
  template: string
}

export type OperationGroup = {
  name: 'Arithmetic' | 'Scientific' | 'Algebra' | 'Calculus'
  items: OperationItem[]
}

export const OPERATION_GROUPS: OperationGroup[] = [
  {
    name: 'Arithmetic',
    items: [
      { id: 'add', label: '+', template: '□ + ' },
      { id: 'subtract', label: '−', template: '□ - ' },
      { id: 'multiply', label: '×', template: '□ * ' },
      { id: 'divide', label: '÷', template: '□ / ' },
      { id: 'power', label: 'xʸ', template: '(□)^2' },
      { id: 'sqrt', label: '√', template: 'sqrt(□)' },
      { id: 'factorial', label: 'n!', template: '(□)!' },
      { id: 'parentheses', label: '( )', template: '(□)' },
    ],
  },
  {
    name: 'Scientific',
    items: [
      { id: 'sin', label: 'sin', template: 'sin(□)' },
      { id: 'cos', label: 'cos', template: 'cos(□)' },
      { id: 'tan', label: 'tan', template: 'tan(□)' },
      { id: 'asin', label: 'sin⁻¹', template: 'asin(□)' },
      { id: 'acos', label: 'cos⁻¹', template: 'acos(□)' },
      { id: 'atan', label: 'tan⁻¹', template: 'atan(□)' },
      { id: 'sinh', label: 'sinh', template: 'sinh(□)' },
      { id: 'cosh', label: 'cosh', template: 'cosh(□)' },
      { id: 'tanh', label: 'tanh', template: 'tanh(□)' },
      { id: 'ln', label: 'ln', template: 'ln(□)' },
      { id: 'log', label: 'log', template: 'log(□)' },
      { id: 'log10', label: 'log₁₀', template: 'log10(□)' },
      { id: 'exp', label: 'eˣ', template: 'exp(□)' },
      { id: 'abs', label: '|x|', template: 'abs(□)' },
      { id: 'pi', label: 'π', template: 'pi' },
      { id: 'e', label: 'e', template: 'e' },
    ],
  },
  {
    name: 'Algebra',
    items: [
      { id: 'simplify', label: 'Simplify', template: 'simplify(□)' },
      { id: 'expand', label: 'Expand', template: 'expand(□)' },
      { id: 'factor', label: 'Factor', template: 'factor(□)' },
    ],
  },
  {
    name: 'Calculus',
    items: [
      { id: 'diff', label: 'Derivative', template: 'diff(□, x)' },
      { id: 'integrate', label: 'Integral', template: 'integrate(□, x)' },
      { id: 'limit', label: 'Limit', template: 'limit(□, x, 0)' },
    ],
  },
]

export type TextSelection = { start: number; end: number }

export function applyInsertion(
  source: string,
  selection: TextSelection,
  template: string,
): { source: string; selection: TextSelection } {
  const start = Math.max(0, Math.min(selection.start, selection.end, source.length))
  const end = Math.max(start, Math.min(Math.max(selection.start, selection.end), source.length))
  const selected = source.slice(start, end)
  const slot = template.indexOf('□')
  const replacement = slot >= 0 ? template.replace('□', selected) : template
  const nextSource = source.slice(0, start) + replacement + source.slice(end)
  const cursor =
    slot >= 0 && selected.length === 0 ? start + slot : start + replacement.length

  return {
    source: nextSource,
    selection: { start: cursor, end: cursor },
  }
}

'use client'

import {
  Calculator,
  ChartNoAxesColumn,
  CircleHelp,
  Eraser,
  Pencil,
  Plus,
  Trash2,
} from 'lucide-react'
import {
  useEffect,
  useMemo,
  useReducer,
  useRef,
  useSyncExternalStore,
} from 'react'

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import {
  Field,
  FieldError,
  FieldLabel,
} from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Separator } from '@/components/ui/separator'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'

import { ResultCard } from '@/registry/calculator/ui/result-card'
import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'
import { relationToMathMl } from '@/registry/calculator/lib/dsl/mathml'
import { parseRelation } from '@/registry/calculator/lib/dsl/parser'
import { HELP_CONTENT_HTML } from '@/registry/calculator/lib/generated/help-content'
import { initialCalculatorState } from '@/registry/calculator/lib/model'
import { applyInsertion, OPERATION_GROUPS } from '@/registry/calculator/lib/operations'
import { calculatorReducer } from '@/registry/calculator/lib/reducer'
import {
  createSolverClient,
  type SolverClient,
  type SolverEngineSnapshot,
} from '@/registry/calculator/lib/solver/client'
import { preflight } from '@/registry/calculator/lib/solver/preflight'
import type { SolverMode, SolverResult } from '@/registry/calculator/lib/solver/protocol'

type ScientificCalculatorProps = { solverClient?: SolverClient }

type EditorParseState =
  | { kind: 'empty' }
  | { kind: 'valid'; ast: RelationAst; mathml: string }
  | { kind: 'invalid'; message: string }

const IDLE_ENGINE: SolverEngineSnapshot = { phase: 'idle' }

function parseEditor(source: string): EditorParseState {
  if (!source.trim()) return { kind: 'empty' }
  try {
    const ast = parseRelation(source)
    return { kind: 'valid', ast, mathml: relationToMathMl(ast) }
  } catch (error) {
    return {
      kind: 'invalid',
      message: error instanceof Error ? error.message : 'This expression is not valid.',
    }
  }
}

export function ScientificCalculator({ solverClient }: ScientificCalculatorProps) {
  const client = useMemo(() => solverClient ?? createSolverClient(), [solverClient])
  const [state, dispatch] = useReducer(calculatorReducer, initialCalculatorState)
  const editorRef = useRef<HTMLInputElement>(null)
  const relationSequence = useRef(0)
  const requestSequence = useRef(0)
  const parsed = useMemo(() => parseEditor(state.source), [state.source])
  const engine = useSyncExternalStore(
    (listener) => client.subscribe(listener),
    () => client.getSnapshot(),
    () => IDLE_ENGINE,
  )

  useEffect(() => {
    client.start()
    if (solverClient) return
    return () => client.dispose()
  }, [client, solverClient])

  function saveRelation() {
    if (parsed.kind !== 'valid') return
    relationSequence.current += 1
    dispatch({
      type: 'save',
      id: `relation-${relationSequence.current}`,
      source: state.source.trim(),
      ast: parsed.ast,
      now: relationSequence.current,
    })
    queueMicrotask(() => editorRef.current?.focus())
  }

  function insertOperation(template: string) {
    const editor = editorRef.current
    const insertion = applyInsertion(
      state.source,
      {
        start: editor?.selectionStart ?? state.source.length,
        end: editor?.selectionEnd ?? state.source.length,
      },
      template,
    )
    dispatch({ type: 'source-changed', source: insertion.source })
    queueMicrotask(() => {
      editorRef.current?.focus()
      editorRef.current?.setSelectionRange(insertion.selection.start, insertion.selection.end)
    })
  }

  async function solveRelations(
    relations: RelationAst[],
    mode: SolverMode = 'system',
  ) {
    if (relations.length === 0) {
      dispatch({
        type: 'local-diagnostic',
        code: 'no-relations',
        message: state.relations.length === 0
          ? 'Add an expression to the shared system first.'
          : 'Enable at least one relation first.',
      })
      return
    }

    requestSequence.current += 1
    const requestId = `calculation-${requestSequence.current}`
    dispatch({ type: 'solve-started', requestId })

    let result: SolverResult
    const validation = preflight(relations)
    if (!validation.ok) {
      result = {
        status: validation.status,
        equationCount: validation.equationCount,
        variableCount: validation.variableCount,
        message: validation.message,
      }
    } else {
      try {
        result = await client.solve(relations, mode)
      } catch (error) {
        result = {
          status: 'error',
          message: error instanceof Error ? error.message : 'The solver stopped unexpectedly.',
        }
      }
    }
    dispatch({ type: 'solve-finished', requestId, result })
  }

  function calculate() {
    return solveRelations(
      state.relations
        .filter((relation) => relation.enabled)
        .map((relation) => relation.ast),
    )
  }

  return (
    <section
      className="mx-auto w-full max-w-6xl p-4 md:p-8"
      aria-label="Scientific calculator workspace"
    >
      <Card>
        <CardContent>
          <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)]">
            <section className="grid content-start gap-4">
              <div className="flex flex-wrap gap-2">
                <Button variant="outline" disabled aria-label="Plot — V2">
                  <ChartNoAxesColumn /> Plot <Badge variant="secondary">V2</Badge>
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  aria-label="Calculator help"
                  onClick={() => dispatch({ type: 'help-changed', open: true })}
                >
                  <CircleHelp />
                </Button>
                {state.editingId ? <Badge>Editing</Badge> : null}
              </div>

              <Field data-invalid={parsed.kind === 'invalid'}>
                <FieldLabel htmlFor="calculator-expression">Calculator expression</FieldLabel>
                <div className="flex items-center gap-2">
                  <Input
                    ref={editorRef}
                    id="calculator-expression"
                    value={state.source}
                    aria-invalid={parsed.kind === 'invalid'}
                    placeholder="2x + 3 = 7"
                    onChange={(event) => dispatch({ type: 'source-changed', source: event.target.value })}
                  />
                  <Button
                    variant="outline"
                    size="icon"
                    aria-label="Clear"
                    onClick={() => dispatch({ type: 'clear-editor' })}
                    disabled={!state.source && !state.editingId}
                  >
                    <Eraser />
                  </Button>
                </div>
                {parsed.kind === 'invalid' ? <FieldError>{parsed.message}</FieldError> : null}
              </Field>

              <div className="flex items-center gap-2">
                <Alert className="min-w-0 flex-1" aria-label="Rendered math preview">
                  <AlertDescription>
                    {parsed.kind === 'valid' ? (
                      <span dangerouslySetInnerHTML={{ __html: parsed.mathml }} />
                    ) : (
                      <span aria-hidden="true">&nbsp;</span>
                    )}
                  </AlertDescription>
                </Alert>
                <Button
                  size="icon"
                  aria-label={state.editingId ? 'Save relation' : 'Add relation'}
                  onClick={saveRelation}
                  disabled={parsed.kind !== 'valid'}
                >
                  <Plus />
                </Button>
              </div>

              <Separator />

              <Tabs defaultValue={OPERATION_GROUPS[0].name}>
                <TabsList>
                  {OPERATION_GROUPS.map((group) => (
                    <TabsTrigger key={group.name} value={group.name}>{group.name}</TabsTrigger>
                  ))}
                </TabsList>
                {OPERATION_GROUPS.map((group) => (
                  <TabsContent key={group.name} value={group.name}>
                    <div className="flex flex-wrap gap-2">
                      {group.items.map((item) => (
                        <Button
                          key={item.id}
                          type="button"
                          variant="outline"
                          size="sm"
                          onClick={() => insertOperation(item.template)}
                        >
                          {item.label}
                        </Button>
                      ))}
                    </div>
                  </TabsContent>
                ))}
              </Tabs>
            </section>

            <Separator className="hidden lg:block" orientation="vertical" />
            <Separator className="lg:hidden" />

            <section className="flex min-h-[32rem] flex-col gap-4">
              <TooltipProvider>
                <div className="grid gap-3">
                  {state.relations.length === 0 ? (
                  <Alert>
                    <AlertTitle>No relations yet</AlertTitle>
                    <AlertDescription>Add an expression from the editor.</AlertDescription>
                  </Alert>
                  ) : state.relations.map((relation, index) => (
                  <div className="grid gap-3" key={relation.id}>
                    <div className="flex items-center gap-3" data-testid="relation-row">
                      <Checkbox
                        checked={relation.enabled}
                        aria-label={`Enable ${relation.source}`}
                        onCheckedChange={(enabled) => {
                          dispatch({ type: 'enabled-changed', id: relation.id, enabled })
                        }}
                      />
                      <span className="min-w-0 flex-1" aria-label={relation.source}>
                        <span
                          aria-hidden="true"
                          dangerouslySetInnerHTML={{ __html: relationToMathMl(relation.ast) }}
                        />
                      </span>
                      <Tooltip>
                        <TooltipTrigger
                          render={(
                            <Button
                              size="icon-sm"
                              aria-label={`Solve ${relation.source}`}
                              disabled={!relation.enabled || state.solver.phase === 'loading'}
                              onClick={() => void solveRelations([relation.ast], 'symbolic')}
                            >
                              <Calculator />
                            </Button>
                          )}
                        />
                        <TooltipContent>Solve</TooltipContent>
                      </Tooltip>
                      <Tooltip>
                        <TooltipTrigger
                          render={(
                            <Button
                              variant="outline"
                              size="icon-sm"
                              aria-label={`Edit ${relation.source}`}
                              onClick={() => {
                                dispatch({ type: 'edit', id: relation.id })
                                queueMicrotask(() => editorRef.current?.focus())
                              }}
                            >
                              <Pencil />
                            </Button>
                          )}
                        />
                        <TooltipContent>Edit</TooltipContent>
                      </Tooltip>
                      <Tooltip>
                        <TooltipTrigger
                          render={(
                            <Button
                              variant="destructive"
                              size="icon-sm"
                              aria-label={`Delete ${relation.source}`}
                              onClick={() => dispatch({ type: 'delete', id: relation.id })}
                            >
                              <Trash2 />
                            </Button>
                          )}
                        />
                        <TooltipContent>Delete</TooltipContent>
                      </Tooltip>
                    </div>
                    {index < state.relations.length - 1 ? <Separator /> : null}
                  </div>
                  ))}
                </div>
              </TooltipProvider>
              <div>
                <Button onClick={() => void calculate()} disabled={state.solver.phase === 'loading'}>
                  <Calculator /> Calculate
                </Button>
              </div>
              <div className="mt-auto grid gap-4">
                <Separator />
                <ResultCard solver={state.solver} engine={engine} onRetry={() => client.retry()} />
              </div>
            </section>
          </div>
        </CardContent>
      </Card>

      <Dialog
        open={state.helpOpen}
        onOpenChange={(open) => dispatch({ type: 'help-changed', open })}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Calculator help</DialogTitle>
            <DialogDescription>Notation and V1 result states.</DialogDescription>
          </DialogHeader>
          <div dangerouslySetInnerHTML={{ __html: HELP_CONTENT_HTML }} />
        </DialogContent>
      </Dialog>
    </section>
  )
}

import {
  initialCalculatorState,
  type CalculatorAction,
  type CalculatorState,
  type Relation,
} from '@/registry/calculator/lib/model'

function idleSolver(): CalculatorState['solver'] {
  return { phase: 'idle' }
}

export function calculatorReducer(
  state: CalculatorState,
  action: CalculatorAction,
): CalculatorState {
  switch (action.type) {
    case 'source-changed':
      return { ...state, source: action.source }
    case 'save': {
      if (state.editingId) {
        return {
          ...state,
          source: '',
          editingId: null,
          solver: idleSolver(),
          relations: state.relations.map((relation) =>
            relation.id === state.editingId
              ? { ...relation, source: action.source, ast: action.ast }
              : relation,
          ),
        }
      }
      const relation: Relation = {
        id: action.id,
        source: action.source,
        ast: action.ast,
        createdAt: action.now,
        enabled: true,
      }
      return {
        ...state,
        source: '',
        relations: [...state.relations, relation],
        solver: idleSolver(),
      }
    }
    case 'edit': {
      const relation = state.relations.find((row) => row.id === action.id)
      return relation
        ? { ...state, source: relation.source, editingId: relation.id }
        : state
    }
    case 'delete': {
      const deletingEditedRow = state.editingId === action.id
      return {
        ...state,
        relations: state.relations.filter((relation) => relation.id !== action.id),
        source: deletingEditedRow ? '' : state.source,
        editingId: deletingEditedRow ? null : state.editingId,
        solver: idleSolver(),
      }
    }
    case 'enabled-changed':
      return {
        ...state,
        relations: state.relations.map((relation) =>
          relation.id === action.id
            ? { ...relation, enabled: action.enabled }
            : relation,
        ),
        solver: idleSolver(),
      }
    case 'clear-editor':
      return { ...state, source: '', editingId: null }
    case 'clear-all':
      return { ...initialCalculatorState, helpOpen: state.helpOpen }
    case 'help-changed':
      return { ...state, helpOpen: action.open }
    case 'local-diagnostic':
      return {
        ...state,
        solver: {
          phase: 'diagnostic',
          code: action.code,
          message: action.message,
        },
      }
    case 'solve-started':
      return { ...state, solver: { phase: 'loading', requestId: action.requestId } }
    case 'solve-finished':
      return state.solver.phase === 'loading' &&
        state.solver.requestId === action.requestId
        ? {
            ...state,
            solver: {
              phase: 'complete',
              requestId: action.requestId,
              result: action.result,
            },
          }
        : state
  }
}

// Generated by scripts/render-calculator-solver-worker.ts.
export const SOLVER_WORKER_SOURCE = "var a=`"""Trusted SymPy adapter for validated calculator AST payloads.

This module deliberately contains no parsing or evaluation of source strings.
Every accepted operation is selected from closed dispatch tables below.
"""

import sympy as sp


class UnsupportedFeature(Exception):
    """Raised when a valid payload asks for a capability outside V1."""


class RealDomainError(Exception):
    """Raised when a valid operation produces a non-real value in real mode."""


class UndefinedDomainError(Exception):
    """Raised when an operation produces an undefined closed value."""


class UnresolvedValueError(Exception):
    """Raised when SymPy cannot establish whether a closed value is real."""


SYMBOLIC_QUERY_OPERATIONS = {
    "simplify",
    "expand",
    "factor",
    "diff",
    "integrate",
    "limit",
}

CALCULUS_BINDING_INDEX = {"diff": 1, "integrate": 1, "limit": 1}


def _collect_symbols(node, names):
    kind = node.get("kind") if isinstance(node, dict) else None
    if kind == "symbol":
        names.add(str(node["name"]).lower())
        return
    if kind in {"number", "constant"}:
        return
    if kind in {"unary", "factorial"}:
        _collect_symbols(node["operand"], names)
        return
    if kind == "binary":
        _collect_symbols(node["left"], names)
        _collect_symbols(node["right"], names)
        return
    if kind == "call":
        binding_index = CALCULUS_BINDING_INDEX.get(node.get("name"))
        for index, argument in enumerate(node.get("args", [])):
            if index != binding_index:
                _collect_symbols(argument, names)
        return
    raise UnsupportedFeature(f"Unsupported AST node: {kind or 'unknown'}")


def _equation_symbol_names(relations):
    names = set()
    for relation in relations:
        if relation.get("kind") != "equation":
            continue
        _collect_symbols(relation["left"], names)
        _collect_symbols(relation["right"], names)
    return sorted(names)


def _number(value):
    try:
        return sp.Rational(str(value))
    except (TypeError, ValueError) as error:
        raise UnsupportedFeature(f"Unsupported number literal: {value}") from error


def _require_symbol(value, operation):
    if not isinstance(value, sp.Symbol):
        raise UnsupportedFeature(f"{operation} requires a variable as its second argument")
    return value


def _build_allowed_call(name, raw_args, symbols):
    args = [build_expr(argument, symbols) for argument in raw_args]
    unary_calls = {
        "sqrt": sp.sqrt,
        "abs": sp.Abs,
        "exp": sp.exp,
        "ln": sp.log,
        "log": sp.log,
        "sin": sp.sin,
        "cos": sp.cos,
        "tan": sp.tan,
        "asin": sp.asin,
        "acos": sp.acos,
        "atan": sp.atan,
        "sinh": sp.sinh,
        "cosh": sp.cosh,
        "tanh": sp.tanh,
        "simplify": sp.simplify,
        "expand": sp.expand,
        "factor": sp.factor,
    }
    if name in unary_calls and len(args) == 1:
        return unary_calls[name](args[0])
    if name == "log10" and len(args) == 1:
        return sp.log(args[0], 10)
    if name == "diff" and len(args) == 2:
        return sp.diff(args[0], _require_symbol(args[1], name))
    if name == "integrate" and len(args) == 2:
        return sp.integrate(args[0], _require_symbol(args[1], name))
    if name == "limit" and len(args) == 3:
        return sp.limit(args[0], _require_symbol(args[1], name), args[2])
    raise UnsupportedFeature(f"Unsupported function or argument count: {name}")


def build_expr(node, symbols):
    if not isinstance(node, dict):
        raise UnsupportedFeature("AST nodes must be objects")
    kind = node.get("kind")
    if kind == "number":
        return _number(node.get("value"))
    if kind == "symbol":
        name = str(node.get("name", "")).lower()
        if not name:
            raise UnsupportedFeature("Symbols must have a name")
        return symbols.setdefault(name, sp.Symbol(name, real=True))
    if kind == "constant":
        constants = {"pi": sp.pi, "e": sp.E}
        name = node.get("name")
        if name not in constants:
            raise UnsupportedFeature(f"Unsupported constant: {name}")
        return constants[name]
    if kind == "unary":
        operand = build_expr(node["operand"], symbols)
        if node.get("operator") == "+":
            return operand
        if node.get("operator") == "-":
            return -operand
        raise UnsupportedFeature(f"Unsupported unary operator: {node.get('operator')}")
    if kind == "binary":
        left = build_expr(node["left"], symbols)
        right = build_expr(node["right"], symbols)
        operator = node.get("operator")
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            return left / right
        if operator == "^":
            return left**right
        raise UnsupportedFeature(f"Unsupported binary operator: {operator}")
    if kind == "factorial":
