  | 'rparen'
  | 'lbrace'
  | 'rbrace'
  | 'comma'
  | 'equals'
  | 'eof'

export type Token = {
  kind: TokenKind
  text: string
  start: number
  end: number
}

export class TokenizeError extends Error {
  readonly start: number
  readonly end: number

  constructor(message: string, start: number, end: number) {
    super(`${message} at position ${start + 1}`)
    this.name = 'TokenizeError'
    this.start = start
    this.end = end
  }
}

const SINGLE_TOKENS: Record<string, TokenKind> = {
  '+': 'plus',
  '-': 'minus',
  '*': 'star',
  '/': 'slash',
  '^': 'caret',
  '!': 'bang',
  '(': 'lparen',
  ')': 'rparen',
  '{': 'lbrace',
  '}': 'rbrace',
  ',': 'comma',
  '=': 'equals',
}

function isDigit(character: string | undefined): boolean {
  return character !== undefined && character >= '0' && character <= '9'
}

function isIdentifierStart(character: string | undefined): boolean {
  return (
    character !== undefined &&
    ((character >= 'a' && character <= 'z') ||
      (character >= 'A' && character <= 'Z') ||
      character === '_')
  )
}

function isIdentifierPart(character: string | undefined): boolean {
  return isIdentifierStart(character) || isDigit(character)
}

function readNumber(source: string, start: number): number {
  let index = start

  while (isDigit(source[index])) index += 1
  if (source[index] === '.') {
    index += 1
    while (isDigit(source[index])) index += 1
  }

  if (source[index]?.toLowerCase() === 'e') {
    let exponentEnd = index + 1
    if (source[exponentEnd] === '+' || source[exponentEnd] === '-') {
      exponentEnd += 1
    }
    const digitStart = exponentEnd
    while (isDigit(source[exponentEnd])) exponentEnd += 1
    if (exponentEnd > digitStart) index = exponentEnd
  }

  return index
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = []
  let index = 0

  while (index < source.length) {
    const character = source[index]
    if (/\s/u.test(character)) {
      index += 1
      continue
    }

    const singleKind = SINGLE_TOKENS[character]
    if (singleKind) {
      tokens.push({ kind: singleKind, text: character, start: index, end: index + 1 })
      index += 1
      continue
    }

    if (isDigit(character) || (character === '.' && isDigit(source[index + 1]))) {
      const end = readNumber(source, index)
      tokens.push({ kind: 'number', text: source.slice(index, end), start: index, end })
      index = end
      continue
    }

    if (isIdentifierStart(character)) {
      let end = index + 1
      while (isIdentifierPart(source[end])) end += 1
      tokens.push({ kind: 'identifier', text: source.slice(index, end), start: index, end })
      index = end
      continue
    }

    throw new TokenizeError(`Unexpected character "${character}"`, index, index + 1)
  }

  tokens.push({ kind: 'eof', text: '', start: source.length, end: source.length })
  return tokens
}

import type { ExpressionAst, RelationAst } from '@/registry/calculator/lib/dsl/ast'

const CALCULUS_BINDING_INDEX = new Map([
  ['diff', 1],
  ['integrate', 1],
  ['limit', 1],
])

export function collectFreeSymbols(expression: ExpressionAst): Set<string> {
  const symbols = new Set<string>()

  function visit(node: ExpressionAst): void {
    switch (node.kind) {
      case 'number':
      case 'constant':
        return
      case 'symbol':
        symbols.add(node.name.toLowerCase())
        return
      case 'unary':
      case 'factorial':
        visit(node.operand)
        return
      case 'binary':
        visit(node.left)
        visit(node.right)
        return
      case 'call': {
        const boundIndex = CALCULUS_BINDING_INDEX.get(node.name)
        node.args.forEach((argument, index) => {
          if (index !== boundIndex) visit(argument)
        })
      }
    }
  }

  visit(expression)
  return symbols
}

export function collectEquationSymbols(relations: RelationAst[]): string[] {
  const symbols = new Set<string>()

  for (const relation of relations) {
    if (relation.kind !== 'equation') continue
    for (const symbol of collectFreeSymbols(relation.left)) symbols.add(symbol)
    for (const symbol of collectFreeSymbols(relation.right)) symbols.add(symbol)
  }

  return [...symbols].sort((left, right) => left.localeCompare(right))
}

import type { BuiltinFunction, ExpressionAst, RelationAst } from '@/registry/calculator/lib/dsl/ast'

type Rendered = { latex: string; precedence: number }

const PRECEDENCE = {
  additive: 1,
  multiplicative: 2,
  unary: 3,
  power: 4,
  factorial: 5,
  atom: 6,
} as const

const NAMED_FUNCTIONS: Partial<Record<BuiltinFunction, string>> = {
  exp: 'exp',
  ln: 'ln',
  log: 'log',
  sin: 'sin',
  cos: 'cos',
  tan: 'tan',
  asin: 'arcsin',
  acos: 'arccos',
  atan: 'arctan',
  sinh: 'sinh',
  cosh: 'cosh',
  tanh: 'tanh',
}

function group(latex: string): string {
  return `\\left(${latex}\\right)`
}

function escapeSymbol(name: string): string {
  const escaped = name.replaceAll('_', '\\_')
  return name.length === 1 ? escaped : `\\mathit{${escaped}}`
}

function wrapped(rendered: Rendered, minimumPrecedence: number): string {
  return rendered.precedence < minimumPrecedence
    ? group(rendered.latex)
    : rendered.latex
}

function renderCall(name: BuiltinFunction, args: ExpressionAst[]): string {
  const renderedArgs = args.map((argument) => render(argument).latex)
  if (name === 'sqrt') return `\\sqrt{${renderedArgs[0]}}`
  if (name === 'abs') return `\\left|${renderedArgs[0]}\\right|`
  if (name === 'log10') return `\\log_{10}${group(renderedArgs[0])}`
  if (name === 'diff') {
    return `\\frac{d}{d ${renderedArgs[1]}}${group(renderedArgs[0])}`
  }
  if (name === 'integrate') {
    return `\\int ${renderedArgs[0]}\\, d${renderedArgs[1]}`
  }
  if (name === 'limit') {
    return `\\lim_{${renderedArgs[1]} \\to ${renderedArgs[2]}}${group(renderedArgs[0])}`
  }
  if (name === 'simplify' || name === 'expand' || name === 'factor') {
    return `\\operatorname{${name}}${group(renderedArgs[0])}`
  }
  const command = NAMED_FUNCTIONS[name]
  return `\\${command ?? name}${group(renderedArgs[0])}`
}

function render(expression: ExpressionAst): Rendered {
  switch (expression.kind) {
    case 'number':
      return { latex: expression.value, precedence: PRECEDENCE.atom }
    case 'symbol':
      return { latex: escapeSymbol(expression.name), precedence: PRECEDENCE.atom }
    case 'constant':
      return {
        latex: expression.name === 'pi' ? '\\pi' : '\\mathrm{e}',
        precedence: PRECEDENCE.atom,
      }
    case 'unary': {
      const operand = render(expression.operand)
      return {
        latex: `${expression.operator}${wrapped(operand, PRECEDENCE.unary)}`,
        precedence: PRECEDENCE.unary,
      }
    }
    case 'factorial': {
      const operand = render(expression.operand)
      return {
        latex: `${wrapped(operand, PRECEDENCE.factorial)}!`,
        precedence: PRECEDENCE.factorial,
      }
    }
    case 'call':
      return {
        latex: renderCall(expression.name, expression.args),
        precedence: PRECEDENCE.atom,
      }
    case 'binary': {
      const left = render(expression.left)
      const right = render(expression.right)
      if (expression.operator === '+' || expression.operator === '-') {
        const rightLatex =
          expression.operator === '-' && right.precedence <= PRECEDENCE.additive
            ? group(right.latex)
            : right.latex
        return {
          latex: `${wrapped(left, PRECEDENCE.additive)} ${expression.operator} ${rightLatex}`,
          precedence: PRECEDENCE.additive,
        }
      }
      if (expression.operator === '/') {
        return {
          latex: `\\frac{${left.latex}}{${right.latex}}`,
          precedence: PRECEDENCE.multiplicative,
        }
      }
      if (expression.operator === '^') {
        const base =
          left.precedence <= PRECEDENCE.power ? group(left.latex) : left.latex
        return {
          latex: `${base}^{${right.latex}}`,
          precedence: PRECEDENCE.power,
        }
      }
      const separator = expression.implicit ? '' : ' \\cdot '
      return {
        latex: `${wrapped(left, PRECEDENCE.multiplicative)}${separator}${wrapped(right, PRECEDENCE.multiplicative)}`,
        precedence: PRECEDENCE.multiplicative,
      }
    }
  }
}

export function toLatex(expression: ExpressionAst): string {
  return render(expression).latex
}

export function relationToLatex(relation: RelationAst): string {
  return relation.kind === 'equation'
    ? `${toLatex(relation.left)} = ${toLatex(relation.right)}`
    : toLatex(relation.expression)
}

import type { BuiltinFunction, ExpressionAst, RelationAst } from '@/registry/calculator/lib/dsl/ast'

type Rendered = { mathml: string; precedence: number }

const PRECEDENCE = {
  additive: 1,
  multiplicative: 2,
  unary: 3,
  power: 4,
  factorial: 5,
  atom: 6,
} as const

const FUNCTION_LABELS: Partial<Record<BuiltinFunction, string>> = {
  asin: 'arcsin',
  acos: 'arccos',
  atan: 'arctan',
  log10: 'log',
}

function escapeXml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;')
}

function row(...children: string[]): string {
  return `<mrow>${children.join('')}</mrow>`
}

function operator(value: string): string {
  return `<mo>${value}</mo>`
}

function identifier(value: string): string {
  return `<mi>${escapeXml(value)}</mi>`
}

function group(mathml: string): string {
  return row(operator('('), mathml, operator(')'))
}

function wrapped(rendered: Rendered, minimumPrecedence: number): string {
  return rendered.precedence < minimumPrecedence
    ? group(rendered.mathml)
    : rendered.mathml
}

function applyFunction(label: string, argument: string): string {
  return row(identifier(label), operator('&#x2061;'), group(argument))
}

function renderCall(name: BuiltinFunction, args: ExpressionAst[]): string {
  const renderedArgs = args.map((argument) => render(argument).mathml)
  if (name === 'sqrt') return `<msqrt>${renderedArgs[0]}</msqrt>`
  if (name === 'abs') return row(operator('|'), renderedArgs[0], operator('|'))
  if (name === 'log10') {
    return row(
      `<msub>${identifier('log')}<mn>10</mn></msub>`,
      operator('&#x2061;'),
      group(renderedArgs[0]),
    )
  }
  if (name === 'diff') {
    return row(
      `<mfrac>${identifier('d')}${row(identifier('d'), renderedArgs[1])}</mfrac>`,
      group(renderedArgs[0]),
    )
  }
  if (name === 'integrate') {
    return row(
      operator('&#x222B;'),
      renderedArgs[0],
      operator('&#x2062;'),
      identifier('d'),
      renderedArgs[1],
    )
  }
  if (name === 'limit') {
    return row(
      `<munder>${identifier('lim')}${row(renderedArgs[1], operator('&#x2192;'), renderedArgs[2])}</munder>`,
      group(renderedArgs[0]),
    )
  }
  return applyFunction(FUNCTION_LABELS[name] ?? name, renderedArgs[0])
}

function render(expression: ExpressionAst): Rendered {
  switch (expression.kind) {
    case 'number':
      return {
        mathml: `<mn>${escapeXml(expression.value)}</mn>`,
        precedence: PRECEDENCE.atom,
      }
    case 'symbol':
      return { mathml: identifier(expression.name), precedence: PRECEDENCE.atom }
    case 'constant':
      return {
        mathml: identifier(expression.name === 'pi' ? 'π' : 'e'),
        precedence: PRECEDENCE.atom,
      }
    case 'unary': {
      const operand = render(expression.operand)
      return {
        mathml: row(operator(expression.operator), wrapped(operand, PRECEDENCE.unary)),
        precedence: PRECEDENCE.unary,
      }
    }
    case 'factorial': {
      const operand = render(expression.operand)
      return {
        mathml: row(wrapped(operand, PRECEDENCE.factorial), operator('!')),
        precedence: PRECEDENCE.factorial,
      }
    }
    case 'call':
      return {
        mathml: renderCall(expression.name, expression.args),
        precedence: PRECEDENCE.atom,
      }
    case 'binary': {
      const left = render(expression.left)
      const right = render(expression.right)
      if (expression.operator === '+' || expression.operator === '-') {
        const rightMathml =
          expression.operator === '-' && right.precedence <= PRECEDENCE.additive
            ? group(right.mathml)
            : right.mathml
        return {
          mathml: row(
            wrapped(left, PRECEDENCE.additive),
            operator(expression.operator),
            rightMathml,
          ),
          precedence: PRECEDENCE.additive,
        }
      }
      if (expression.operator === '/') {
        return {
          mathml: `<mfrac>${left.mathml}${right.mathml}</mfrac>`,
          precedence: PRECEDENCE.multiplicative,
        }
      }
      if (expression.operator === '^') {
        const base =
          left.precedence <= PRECEDENCE.power
            ? group(left.mathml)
            : left.mathml
        return {
          mathml: `<msup>${base}${right.mathml}</msup>`,
          precedence: PRECEDENCE.power,
        }
      }
      return {
        mathml: row(
          wrapped(left, PRECEDENCE.multiplicative),
          operator(expression.implicit ? '&#x2062;' : '&#x22C5;'),
          wrapped(right, PRECEDENCE.multiplicative),
        ),
        precedence: PRECEDENCE.multiplicative,
      }
    }
  }
}

export function toMathMl(expression: ExpressionAst): string {
  return `<math xmlns="http://www.w3.org/1998/Math/MathML">${render(expression).mathml}</math>`
}

export function relationToMathMl(relation: RelationAst): string {
  const content =
    relation.kind === 'equation'
      ? row(render(relation.left).mathml, operator('='), render(relation.right).mathml)
      : render(relation.expression).mathml
  return `<math xmlns="http://www.w3.org/1998/Math/MathML">${content}</math>`
}

import {
  BUILTIN_ARITY,
  isBuiltinFunction,
  type BuiltinFunction,
  type ExpressionAst,
  type RelationAst,
} from '@/registry/calculator/lib/dsl/ast'
import { tokenize, type Token, type TokenKind } from '@/registry/calculator/lib/dsl/tokenize'

export class ParseError extends Error {
  readonly start: number
  readonly end: number

  constructor(message: string, start: number, end: number) {
    super(`${message} at position ${start + 1}`)
    this.name = 'ParseError'
    this.start = start
    this.end = end
  }
}

class Parser {
  private readonly tokens: Token[]
  private index = 0

  constructor(tokens: Token[]) {
    this.tokens = tokens
  }

  parseRelation(): RelationAst {
    const left = this.parseExpression()
    if (this.match('equals')) {
      const right = this.parseExpression()
      this.expectEnd()
      return { kind: 'equation', left, right }
    }
    this.expectEnd()
    return { kind: 'query', expression: left }
  }

  private parseExpression(): ExpressionAst {
    return this.parseAdditive()
  }

  private parseAdditive(): ExpressionAst {
    let expression = this.parseMultiplicative()
    while (this.at('plus') || this.at('minus')) {
      const operator = this.advance().kind === 'plus' ? '+' : '-'
      expression = {
        kind: 'binary',
        operator,
        left: expression,
        right: this.parseMultiplicative(),
      }
    }
    return expression
  }

  private parseMultiplicative(): ExpressionAst {
    let expression = this.parseUnary()

    while (true) {
      if (this.at('star') || this.at('slash')) {
        const operator = this.advance().kind === 'star' ? '*' : '/'
        expression = {
          kind: 'binary',
          operator,
          left: expression,
          right: this.parseUnary(),
        }
        continue
      }
      if (this.startsImplicitFactor()) {
        expression = {
          kind: 'binary',
          operator: '*',
          implicit: true,
          left: expression,
          right: this.parseUnary(),
        }
        continue
      }
      break
    }

    return expression
  }

  private parseUnary(): ExpressionAst {
    if (this.at('plus') || this.at('minus')) {
      const operator = this.advance().kind === 'plus' ? '+' : '-'
      return { kind: 'unary', operator, operand: this.parseUnary() }
    }
    return this.parsePower()
  }

  private parsePower(): ExpressionAst {
    let expression = this.parsePostfix()
    if (this.match('caret')) {
      expression = {
        kind: 'binary',
        operator: '^',
        left: expression,
        right: this.parseUnary(),
      }
    }
    return expression
  }

  private parsePostfix(): ExpressionAst {
    let expression = this.parsePrimary()
    while (this.match('bang')) expression = { kind: 'factorial', operand: expression }
    return expression
  }

  private parsePrimary(): ExpressionAst {
    const token = this.current()
    if (this.match('number')) return { kind: 'number', value: token.text }

    if (this.match('identifier')) {
      const normalized = token.text.toLowerCase()
      if (isBuiltinFunction(normalized)) {
        if (!this.at('lparen') && !this.at('lbrace')) {
          throw new ParseError(
            `Function "${token.text}" requires parentheses or braces`,
            token.start,
            token.end,
          )
        }
        return this.parseCall(normalized, token)
      }
      if (normalized === 'pi' || normalized === 'e') {
        return { kind: 'constant', name: normalized }
      }
      if (token.text.length > 1 && (this.at('lparen') || this.at('lbrace'))) {
        throw new ParseError(
          `Unknown function "${token.text}"`,
          token.start,
          token.end,
        )
      }
      return { kind: 'symbol', name: token.text }
    }

    if (this.at('lparen') || this.at('lbrace')) {
      const opening = this.advance()
      const closingKind = opening.kind === 'lparen' ? 'rparen' : 'rbrace'
      const closingText = opening.kind === 'lparen' ? ')' : '}'
      const expression = this.parseExpression()
      this.expect(closingKind, `Expected "${closingText}"`)
      return expression
    }

    const shown = token.kind === 'eof' ? 'end of input' : `"${token.text}"`
    throw new ParseError(`Expected an expression, found ${shown}`, token.start, token.end)
  }

  private parseCall(name: BuiltinFunction, nameToken: Token): ExpressionAst {
    const opening = this.advance()
    const closingKind = opening.kind === 'lparen' ? 'rparen' : 'rbrace'
    const closingText = opening.kind === 'lparen' ? ')' : '}'
    const args: ExpressionAst[] = []

    if (!this.at(closingKind)) {
      do {
        args.push(this.parseExpression())
      } while (this.match('comma'))
    }
    this.expect(closingKind, `Expected "${closingText}"`)

    const expected = BUILTIN_ARITY[name]
    if (args.length !== expected) {
      throw new ParseError(
        `${name} expects ${expected} argument${expected === 1 ? '' : 's'}`,
        nameToken.start,
        nameToken.end,
      )
    }
    return { kind: 'call', name, args }
  }

  private startsImplicitFactor(): boolean {
    return (
      this.at('number') ||
      this.at('identifier') ||
      this.at('lparen') ||
      this.at('lbrace')
    )
  }

  private expectEnd(): void {
    if (this.at('eof')) return
    const token = this.current()
    throw new ParseError(
      `Unexpected "${token.text}"; expected end of input`,
      token.start,
      token.end,
    )
  }

  private expect(kind: TokenKind, message: string): Token {
    if (this.at(kind)) return this.advance()
    const token = this.current()
    throw new ParseError(message, token.start, token.end)
  }

  private match(kind: TokenKind): boolean {
    if (!this.at(kind)) return false
    this.advance()
    return true
  }

  private at(kind: TokenKind): boolean {
    return this.current().kind === kind
  }

  private current(): Token {
    return this.tokens[this.index]
  }

  private advance(): Token {
    const token = this.current()
    if (token.kind !== 'eof') this.index += 1
    return token
  }
}

export function parseRelation(source: string): RelationAst {
  return new Parser(tokenize(source)).parseRelation()
}

export const BUILTIN_ARITY = {
  sqrt: 1,
  abs: 1,
  exp: 1,
  ln: 1,
  log: 1,
  log10: 1,
  sin: 1,
  cos: 1,
  tan: 1,
  asin: 1,
  acos: 1,
  atan: 1,
  sinh: 1,
  cosh: 1,
  tanh: 1,
  simplify: 1,
  expand: 1,
  factor: 1,
  diff: 2,
  integrate: 2,
  limit: 3,
} as const

export type BuiltinFunction = keyof typeof BUILTIN_ARITY

export type ExpressionAst =
  | { kind: 'number'; value: string }
  | { kind: 'symbol'; name: string }
  | { kind: 'constant'; name: 'pi' | 'e' }
  | { kind: 'unary'; operator: '+' | '-'; operand: ExpressionAst }
  | {
      kind: 'binary'
      operator: '+' | '-' | '*' | '/' | '^'
      left: ExpressionAst
      right: ExpressionAst
      implicit?: boolean
    }
  | { kind: 'factorial'; operand: ExpressionAst }
  | { kind: 'call'; name: BuiltinFunction; args: ExpressionAst[] }

export type RelationAst =
  | { kind: 'equation'; left: ExpressionAst; right: ExpressionAst }
  | { kind: 'query'; expression: ExpressionAst }

export function isBuiltinFunction(name: string): name is BuiltinFunction {
  return Object.hasOwn(BUILTIN_ARITY, name)
}

import { AlertCircle, CheckCircle2, Info } from 'lucide-react'

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'

import type { SolverState } from '@/registry/calculator/lib/model'
import type { SolverEngineSnapshot } from '@/registry/calculator/lib/solver/client'
import type { DisplayValue, SolverResult } from '@/registry/calculator/lib/solver/protocol'

type ResultCardProps = {
  solver: SolverState
  engine: SolverEngineSnapshot
  onRetry(): void
}

function Value({ value }: { value: DisplayValue }) {
  return (
    <span>
      <span
        aria-hidden="true"
        dangerouslySetInnerHTML={{
          __html: `<math xmlns="http://www.w3.org/1998/Math/MathML">${value.mathml}</math>`,
        }}
      />
      <code className="sr-only">{value.exact}</code>
      {value.approximate ? ` ≈ ${value.approximate}` : null}
    </span>
  )
}

function Solved({ result }: { result: Extract<SolverResult, { status: 'solved' }> }) {
  return (
    <div className="grid gap-3">
      <Alert>
        <CheckCircle2 />
        <AlertTitle>Solved over the reals</AlertTitle>
        <AlertDescription>
          {result.solutions.length}{' '}
          {result.solutions.length === 1 ? 'solution' : 'solutions'} found.
        </AlertDescription>
      </Alert>
      {result.solutions.map((solution, index) => (
        <section className="grid gap-2" key={`solution-${index + 1}`}>
          <h3 className="text-sm font-medium">Solution {index + 1}</h3>
          <dl className="grid gap-2">
            {Object.entries(solution.assignments).map(([name, value]) => (
              <div className="flex items-center justify-between gap-4" key={name}>
                <dt>{name}</dt>
                <dd><Value value={value} /></dd>
              </div>
            ))}
            {solution.queries.map((value, queryIndex) => (
              <div className="flex items-center justify-between gap-4" key={`query-${queryIndex + 1}`}>
                <dt>Query {queryIndex + 1}</dt>
                <dd><Value value={value} /></dd>
              </div>
            ))}
          </dl>
        </section>
      ))}
    </div>
  )
}

function Diagnostic({
  result,
  onRetry,
}: {
  result: Exclude<SolverResult, { status: 'solved' }>
  onRetry(): void
}) {
  return (
    <Alert variant={result.status === 'error' ? 'destructive' : 'default'}>
      <AlertCircle />
      <AlertTitle>{result.status.replaceAll('-', ' ')}</AlertTitle>
      <AlertDescription>{result.message}</AlertDescription>
      {result.status === 'error' ? (
        <Button variant="outline" size="sm" onClick={onRetry}>
          Retry Python engine
        </Button>
      ) : null}
    </Alert>
  )
}

export function ResultCard({ solver, engine, onRetry }: ResultCardProps) {
  let content

  if (solver.phase === 'loading') {
    content = (
      <Alert>
        <Spinner />
        <AlertTitle>
          {engine.phase === 'loading' ? 'Preparing Python engine' : 'Calculating'}
        </AlertTitle>
        <AlertDescription>The first calculation may take a moment.</AlertDescription>
      </Alert>
    )
  } else if (solver.phase === 'diagnostic') {
    content = (
      <Alert>
        <Info />
        <AlertTitle>Add a relation first</AlertTitle>
        <AlertDescription>{solver.message}</AlertDescription>
      </Alert>
    )
  } else if (solver.phase === 'complete') {
    content = solver.result.status === 'solved'
      ? <Solved result={solver.result} />
      : <Diagnostic result={solver.result} onRetry={onRetry} />
  } else if (engine.phase === 'failed') {
    content = (
      <Diagnostic
        result={{ status: 'error', message: engine.message }}
        onRetry={onRetry}
      />
    )
  } else {
    content = (
      <Alert>
        <Info />
        <AlertTitle>Ready to calculate</AlertTitle>
        <AlertDescription>Results and diagnostics will appear here.</AlertDescription>
      </Alert>
    )
  }

  return (
    <section className="grid gap-3" aria-label="Calculation result" aria-live="polite">
      {content}
    </section>
  )
}

import type { PyodideAPI } from 'pyodide'
import { SOLVER_SOURCE } from '@/registry/calculator/lib/generated/solver-source'
import type { SolverRequest, SolverWorkerMessage } from '@/registry/calculator/lib/solver/protocol'

type WorkerScope = {
  onmessage: ((event: MessageEvent<SolverRequest>) => void) | null
  postMessage(message: SolverWorkerMessage): void
}

const workerScope = globalThis as unknown as WorkerScope
const PYODIDE_INDEX_URL =
  'https://cdn.jsdelivr.net/pyodide/v314.0.6/full/'

async function initialize(): Promise<PyodideAPI> {
  try {
    const pyodideModule = (await import(
      /* @vite-ignore */ /* webpackIgnore: true */ `${PYODIDE_INDEX_URL}pyodide.mjs`
    )) as typeof import('pyodide')
    const pyodide = await pyodideModule.loadPyodide({
      indexURL: PYODIDE_INDEX_URL,
    })
    await pyodide.loadPackage('sympy')
    pyodide.FS.writeFile('calculator_solver.py', SOLVER_SOURCE)
    await pyodide.runPythonAsync('from calculator_solver import solve_payload')
    workerScope.postMessage({ type: 'ready' })
    return pyodide
  } catch (error) {
    workerScope.postMessage({
      type: 'init-error',
      message:
        error instanceof Error
          ? `The Python solver could not start: ${error.message}`
          : 'The Python solver could not start.',
    })
    throw error
  }
}

const pyodidePromise = initialize()
let calculationQueue = Promise.resolve()

async function solve(request: SolverRequest): Promise<void> {
  try {
    const pyodide = await pyodidePromise
    pyodide.globals.set(
      '_calculator_payload_json',
      JSON.stringify({ mode: request.mode, relations: request.relations }),
    )
    try {
      const resultJson = await pyodide.runPythonAsync(`
import json
json.dumps(solve_payload(json.loads(_calculator_payload_json)))
`)
      workerScope.postMessage({
        type: 'result',
        id: request.id,
        result: JSON.parse(String(resultJson)),
      })
    } finally {
      pyodide.globals.delete('_calculator_payload_json')
    }
  } catch (error) {
    workerScope.postMessage({
      type: 'result',
      id: request.id,
      result: {
        status: 'error',
        message:
          error instanceof Error
            ? `Solver error: ${error.message}`
            : 'The solver stopped unexpectedly.',
      },
    })
  }
}

workerScope.onmessage = (event) => {
  calculationQueue = calculationQueue.then(() => solve(event.data))
}

import { collectEquationSymbols } from '@/registry/calculator/lib/dsl/analyze'
import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'

export type PreflightResult =
  | { ok: true; equationCount: number; variableCount: number }
  | {
      ok: false
      status: 'overdefined'
      equationCount: number
      variableCount: number
      message: string
    }

export function preflight(relations: RelationAst[]): PreflightResult {
  const equationCount = relations.filter(
    (relation) => relation.kind === 'equation',
  ).length
  const variableCount = collectEquationSymbols(relations).length

  if (equationCount > variableCount) {
    return {
      ok: false,
      status: 'overdefined',
      equationCount,
      variableCount,
      message: `${equationCount} equation${equationCount === 1 ? '' : 's'} exceeds ${variableCount} distinct unknowns.`,
    }
  }

  return { ok: true, equationCount, variableCount }
}

import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'

export type DisplayValue = {
  exact: string
  mathml: string
  approximate?: string
}

export type SolutionResult = {
  assignments: Record<string, DisplayValue>
  queries: DisplayValue[]
}

export type SolverResult =
  | {
      status: 'solved'
      variables: string[]
      solutions: SolutionResult[]
    }
  | { status: 'no-solution'; message: string }
  | { status: 'underdetermined'; symbols: string[]; message: string }
  | {
      status: 'overdefined'
      equationCount: number
      variableCount: number
      message: string
    }
  | { status: 'unresolved'; message: string; detail?: string }
  | { status: 'unsupported'; message: string; feature?: string }
  | { status: 'error'; message: string }

export type SolverMode = 'system' | 'symbolic'

export type SolverRequest = {
  type: 'solve'
  id: string
  relations: RelationAst[]
  mode: SolverMode
}

export type SolverWorkerMessage =
  | { type: 'ready' }
  | { type: 'init-error'; message: string }
  | { type: 'result'; id: string; result: SolverResult }

import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'
import { SOLVER_WORKER_SOURCE } from '@/registry/calculator/lib/generated/solver-worker-source'
import type {
  SolverRequest,
  SolverMode,
  SolverResult,
  SolverWorkerMessage,
} from '@/registry/calculator/lib/solver/protocol'

export type SolverEngineSnapshot =
  | { phase: 'idle' }
  | { phase: 'loading' }
  | { phase: 'ready' }
  | { phase: 'failed'; message: string }

export interface WorkerLike {
  onmessage: ((event: MessageEvent<SolverWorkerMessage>) => void) | null
  onerror: ((event: ErrorEvent) => void) | null
  postMessage(message: SolverRequest): void
  terminate(): void
}

export interface SolverClient {
  start(): void
  solve(relations: RelationAst[], mode?: SolverMode): Promise<SolverResult>
  getSnapshot(): SolverEngineSnapshot
  subscribe(listener: () => void): () => void
  retry(): void
  dispose(): void
}

type WorkerFactory = () => WorkerLike

type ActiveRequest = {
  request: SolverRequest
  resolve(result: SolverResult): void
  posted: boolean
}

const defaultWorkerFactory: WorkerFactory = () => {
  const workerUrl = URL.createObjectURL(
    new Blob([SOLVER_WORKER_SOURCE], { type: 'text/javascript' }),
  )
  const worker = new Worker(workerUrl, { type: 'module' })
  const terminate = worker.terminate.bind(worker)
  worker.terminate = () => {
    URL.revokeObjectURL(workerUrl)
    terminate()
  }
  return worker
}

export function createSolverClient(
  workerFactory: WorkerFactory = defaultWorkerFactory,
): SolverClient {
  let worker: WorkerLike | null = null
  let snapshot: SolverEngineSnapshot = { phase: 'idle' }
  let sequence = 0
  const listeners = new Set<() => void>()
  let queued: SolverRequest | null = null
  let active: ActiveRequest | null = null

  function publish(next: SolverEngineSnapshot): void {
    snapshot = next
    for (const listener of listeners) listener()
  }

  function settleActive(message: string): void {
    active?.resolve({ status: 'error', message })
    active = null
    queued = null
  }

  function handleMessage(
    source: WorkerLike,
    message: SolverWorkerMessage,
  ): void {
    if (source !== worker) return
    if (message.type === 'ready') {
      publish({ phase: 'ready' })
      if (queued && active?.request.id === queued.id) {
        active.posted = true
        source.postMessage(queued)
        queued = null
      }
      return
    }
    if (message.type === 'init-error') {
      publish({ phase: 'failed', message: message.message })
      settleActive(message.message)
      return
    }
    if (!active || active.request.id !== message.id) return
    const { resolve } = active
    active = null
    resolve(message.result)
  }

  function startWorker(): void {
    publish({ phase: 'loading' })
    try {
      const nextWorker = workerFactory()
      worker = nextWorker
      nextWorker.onmessage = (event) => handleMessage(nextWorker, event.data)
      nextWorker.onerror = (event) => {
        if (nextWorker !== worker) return
        const message = event.message || 'The solver worker stopped unexpectedly.'
        publish({ phase: 'failed', message })
        settleActive(message)
      }
    } catch (error) {
      worker = null
      const message =
        error instanceof Error ? error.message : 'The solver worker could not start.'
      publish({ phase: 'failed', message })
      settleActive(message)
    }
  }

  return {
    start() {
      if (!worker) startWorker()
    },
    solve(relations, mode = 'system') {
      if (active) {
        const restartWorker = active.posted
        settleActive('This calculation was superseded by a newer request.')
        if (restartWorker) {
          worker?.terminate()
          worker = null
        }
      }
      if (snapshot.phase === 'failed') {
        worker?.terminate()
        worker = null
      }
      const request: SolverRequest = {
        type: 'solve',
        id: `solve-${Date.now()}-${++sequence}`,
        relations,
        mode,
      }
      const promise = new Promise<SolverResult>((resolve) => {
        active = { request, resolve, posted: false }
      })
      if (!worker) startWorker()
      if (!active || active.request.id !== request.id) return promise
      if (worker && snapshot.phase === 'ready') {
        active.posted = true
        worker.postMessage(request)
      } else if (snapshot.phase !== 'failed') {
        queued = request
      }
      return promise
    },
    getSnapshot() {
      return snapshot
    },
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    retry() {
      worker?.terminate()
      worker = null
      settleActive('The solver restarted before the calculation finished.')
      startWorker()
    },
    dispose() {
      worker?.terminate()
      worker = null
      settleActive('The solver was closed before the calculation finished.')
      publish({ phase: 'idle' })
      listeners.clear()
    },
  }
}

"""Trusted SymPy adapter for validated calculator AST payloads.

This module deliberately contains no parsing or evaluation of source strings.
Every accepted operation is selected from closed dispatch tables below.
"""

import sympy as sp


class UnsupportedFeature(Exception):
    """Raised when a valid payload asks for a capability outside V1."""


class RealDomainError(Exception):
    """Raised when a valid operation produces a non-real value in real mode."""


class UndefinedDomainError(Exception):
    """Raised when an operation produces an undefined closed value."""


class UnresolvedValueError(Exception):
    """Raised when SymPy cannot establish whether a closed value is real."""


SYMBOLIC_QUERY_OPERATIONS = {
    "simplify",
    "expand",
    "factor",
    "diff",
    "integrate",
    "limit",
}

CALCULUS_BINDING_INDEX = {"diff": 1, "integrate": 1, "limit": 1}


def _collect_symbols(node, names):
    kind = node.get("kind") if isinstance(node, dict) else None
    if kind == "symbol":
        names.add(str(node["name"]).lower())
        return
    if kind in {"number", "constant"}:
        return
    if kind in {"unary", "factorial"}:
        _collect_symbols(node["operand"], names)
        return
    if kind == "binary":
        _collect_symbols(node["left"], names)
        _collect_symbols(node["right"], names)
        return
    if kind == "call":
        binding_index = CALCULUS_BINDING_INDEX.get(node.get("name"))
        for index, argument in enumerate(node.get("args", [])):
            if index != binding_index:
                _collect_symbols(argument, names)
        return
    raise UnsupportedFeature(f"Unsupported AST node: {kind or 'unknown'}")


def _equation_symbol_names(relations):
    names = set()
    for relation in relations:
        if relation.get("kind") != "equation":
            continue
        _collect_symbols(relation["left"], names)
        _collect_symbols(relation["right"], names)
    return sorted(names)


def _number(value):
    try:
        return sp.Rational(str(value))
    except (TypeError, ValueError) as error:
        raise UnsupportedFeature(f"Unsupported number literal: {value}") from error


def _require_symbol(value, operation):
    if not isinstance(value, sp.Symbol):
        raise UnsupportedFeature(f"{operation} requires a variable as its second argument")
    return value


def _build_allowed_call(name, raw_args, symbols):
    args = [build_expr(argument, symbols) for argument in raw_args]
    unary_calls = {
        "sqrt": sp.sqrt,
        "abs": sp.Abs,
        "exp": sp.exp,
        "ln": sp.log,
        "log": sp.log,
        "sin": sp.sin,
        "cos": sp.cos,
        "tan": sp.tan,
        "asin": sp.asin,
        "acos": sp.acos,
        "atan": sp.atan,
        "sinh": sp.sinh,
        "cosh": sp.cosh,
        "tanh": sp.tanh,
        "simplify": sp.simplify,
        "expand": sp.expand,
        "factor": sp.factor,
    }
    if name in unary_calls and len(args) == 1:
        return unary_calls[name](args[0])
    if name == "log10" and len(args) == 1:
        return sp.log(args[0], 10)
    if name == "diff" and len(args) == 2:
        return sp.diff(args[0], _require_symbol(args[1], name))
    if name == "integrate" and len(args) == 2:
        return sp.integrate(args[0], _require_symbol(args[1], name))
    if name == "limit" and len(args) == 3:
        return sp.limit(args[0], _require_symbol(args[1], name), args[2])
    raise UnsupportedFeature(f"Unsupported function or argument count: {name}")


def build_expr(node, symbols):
    if not isinstance(node, dict):
        raise UnsupportedFeature("AST nodes must be objects")
    kind = node.get("kind")
    if kind == "number":
        return _number(node.get("value"))
    if kind == "symbol":
        name = str(node.get("name", "")).lower()
        if not name:
            raise UnsupportedFeature("Symbols must have a name")
        return symbols.setdefault(name, sp.Symbol(name, real=True))
    if kind == "constant":
        constants = {"pi": sp.pi, "e": sp.E}
        name = node.get("name")
        if name not in constants:
            raise UnsupportedFeature(f"Unsupported constant: {name}")
        return constants[name]
    if kind == "unary":
        operand = build_expr(node["operand"], symbols)
        if node.get("operator") == "+":
            return operand
        if node.get("operator") == "-":
            return -operand
        raise UnsupportedFeature(f"Unsupported unary operator: {node.get('operator')}")
    if kind == "binary":
        left = build_expr(node["left"], symbols)
        right = build_expr(node["right"], symbols)
        operator = node.get("operator")
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            return left / right
        if operator == "^":
            return left**right
        raise UnsupportedFeature(f"Unsupported binary operator: {operator}")
    if kind == "factorial":
        return sp.factorial(build_expr(node["operand"], symbols))
    if kind == "call":
        return _build_allowed_call(node.get("name"), node.get("args", []), symbols)
    raise UnsupportedFeature(f"Unsupported AST node: {kind or 'unknown'}")


def _underdetermined(symbols):
    names = sorted({str(symbol) for symbol in symbols})
    return {
        "status": "underdetermined",
        "symbols": names,
        "message": "The saved relations leave "
        + (", ".join(names) if names else "one or more values")
        + " undetermined.",
    }


def _set_has_continuum(value):
    if value in {sp.S.Reals, sp.S.Complexes, sp.S.UniversalSet}:
        return True
    if isinstance(value, sp.Interval):
        return True
    if isinstance(value, sp.Union):
        return any(_set_has_continuum(argument) for argument in value.args)
    return False


def _classify_nested_sets(values, variables):
    nested_sets = [value for value in values if isinstance(value, sp.Set)]
    if not nested_sets:
        return None
    if any(value == sp.EmptySet for value in nested_sets):
        return {"status": "no-solution", "message": "No real solution exists."}
    if any(_set_has_continuum(value) for value in nested_sets):
        return _underdetermined(variables)
    return {
        "status": "unresolved",
        "message": "SymPy returned a non-finite solution representation.",
        "detail": str(tuple(nested_sets)),
    }


def classify_solution_set(solution_set, variables, allow_symbolic=False):
    """Classify a SymPy set without conflating unknown and empty results."""
    if solution_set is sp.EmptySet or solution_set == sp.EmptySet:
        return {"status": "no-solution", "message": "No real solution exists."}
    if isinstance(solution_set, sp.ConditionSet):
        return {
            "status": "unresolved",
            "message": "SymPy could not resolve this system to a finite solution set.",
            "detail": str(solution_set),
        }
    if not isinstance(solution_set, sp.FiniteSet):
        return {
            "status": "unresolved",
            "message": "SymPy returned a non-finite solution representation.",
            "detail": str(solution_set),
        }

    candidates = []
    for item in solution_set:
        values = tuple(item) if isinstance(item, (tuple, sp.Tuple)) else (item,)
        if len(values) != len(variables):
            return _underdetermined(variables)
        nested_classification = _classify_nested_sets(values, variables)
        if nested_classification:
            if nested_classification["status"] == "no-solution":
                continue
            return nested_classification
        if any(value.free_symbols for value in values) and not allow_symbolic:
            return _underdetermined(variables)
        if any(value.is_real is False for value in values):
            continue
        candidates.append(values)

    if not candidates:
        return {"status": "no-solution", "message": "No real solution exists."}

    candidates.sort(key=sp.default_sort_key)
    deduplicated = []
    seen = set()
    for candidate in candidates:
        key = tuple(sp.srepr(sp.simplify(value)) for value in candidate)
        if key not in seen:
            seen.add(key)
            deduplicated.append(candidate)
    return {"status": "solved", "raw_solutions": deduplicated}


def _display_value(value):
    exact_value = value
    display = {
        "exact": str(exact_value),
        "mathml": sp.mathml(exact_value, printer="presentation"),
    }
    if not exact_value.free_symbols and exact_value.is_number and not exact_value.is_Integer:
        approximate = str(sp.N(exact_value, 12))
        if approximate != display["exact"]:
            display["approximate"] = approximate
    return display


def _query_allows_symbolic_result(relation):
    expression = relation.get("expression", {})
    return (
        expression.get("kind") == "call"
        and expression.get("name") in SYMBOLIC_QUERY_OPERATIONS
    )


def _evaluate_queries(query_rows, symbols, assignments, allow_symbolic=False):
    values = []
    unresolved_symbols = set()
    for relation in query_rows:
        value = build_expr(relation["expression"], symbols).subs(assignments, simultaneous=True)
        if not _query_allows_symbolic_result(relation):
            value = sp.simplify(value)
        if value.has(sp.nan, sp.zoo):
            raise UndefinedDomainError(
                "This query is undefined in V1 real mode."
            )
        if value.is_real is False:
            raise RealDomainError(
                "This query produces a complex value, which is outside V1 real mode."
            )
        if not value.free_symbols and value.is_real is None:
            raise UnresolvedValueError(
                "SymPy could not establish a valid real value for this query."
            )
        if (
            value.free_symbols
            and not allow_symbolic
            and not _query_allows_symbolic_result(relation)
        ):
            unresolved_symbols.update(value.free_symbols)
        values.append(value)
    return values, unresolved_symbols


def _validate_candidates(candidates, equations, variables):
    valid = []
    unresolved = False
    for values in candidates:
        assignments = dict(zip(variables, values, strict=True))
        candidate_valid = True
        for equation in equations:
            residual = sp.simplify(equation.subs(assignments, simultaneous=True))
            if residual == 0 or residual.is_zero is True:
                continue
            if residual.is_zero is False:
                candidate_valid = False
                break
            unresolved = True
            candidate_valid = False
            break
        if candidate_valid:
            valid.append((values, assignments))
    return valid, unresolved


def solve_payload(payload):
    try:
        relations = payload.get("relations", []) if isinstance(payload, dict) else []
        if not relations:
            return {"status": "error", "message": "No relations were supplied."}
        mode = payload.get("mode", "system")
        if mode not in {"system", "symbolic"}:
            raise UnsupportedFeature(f"Unsupported solver mode: {mode}")
        allow_symbolic = mode == "symbolic"

        equation_rows = [row for row in relations if row.get("kind") == "equation"]
        query_rows = [row for row in relations if row.get("kind") == "query"]
        if len(equation_rows) + len(query_rows) != len(relations):
            raise UnsupportedFeature("Relations must be equations or queries")

        variable_names = _equation_symbol_names(relations)
        equation_count = len(equation_rows)
        if equation_count > len(variable_names):
            return {
                "status": "overdefined",
                "equationCount": equation_count,
                "variableCount": len(variable_names),
                "message": f"{equation_count} equation{'s' if equation_count != 1 else ''} exceeds {len(variable_names)} distinct unknowns.",
            }

        symbols = {name: sp.Symbol(name, real=True) for name in variable_names}
        variables = [symbols[name] for name in variable_names]
        equations = [
            build_expr(row["left"], symbols) - build_expr(row["right"], symbols)
            for row in equation_rows
        ]

        if not equations:
            query_values, free = _evaluate_queries(
                query_rows, symbols, {}, allow_symbolic=allow_symbolic
            )
            if free:
                return _underdetermined(free)
            return {
                "status": "solved",
                "variables": [],
                "solutions": [
                    {
                        "assignments": {},
                        "queries": [_display_value(value) for value in query_values],
                    }
                ],
            }

        solution_set = sp.nonlinsolve(equations, variables)
        classification = classify_solution_set(
            solution_set, variables, allow_symbolic=allow_symbolic
        )
        if classification["status"] != "solved":
            return classification

        valid, validation_unresolved = _validate_candidates(
            classification["raw_solutions"], equations, variables
        )
        if validation_unresolved:
            return {
                "status": "unresolved",
                "message": "SymPy produced candidates that could not be verified exactly.",
            }
        if not valid:
            return {"status": "no-solution", "message": "No real solution exists."}

        display_variables = [
            variable
            for variable in variables
            if not allow_symbolic
            or any(assignments[variable] != variable for _, assignments in valid)
        ]
        serialized_solutions = []
        for _, assignments in valid:
            query_values, free = _evaluate_queries(
                query_rows,
                symbols,
                assignments,
                allow_symbolic=allow_symbolic,
            )
            if free:
                return _underdetermined(free)
            serialized_solutions.append(
                {
                    "assignments": {
                        str(variable): _display_value(assignments[variable])
                        for variable in display_variables
                    },
                    "queries": [_display_value(value) for value in query_values],
                }
            )

        return {
            "status": "solved",
            "variables": [str(variable) for variable in display_variables],
            "solutions": serialized_solutions,
        }
    except UndefinedDomainError as error:
        return {
            "status": "unsupported",
            "message": str(error),
            "feature": "undefined-domain",
        }
    except UnresolvedValueError as error:
        return {
            "status": "unresolved",
            "message": str(error),
        }
    except RealDomainError as error:
        return {
            "status": "unsupported",
            "message": str(error),
            "feature": "complex-domain",
        }
    except UnsupportedFeature as error:
        return {
            "status": "unsupported",
            "message": str(error),
            "feature": str(error),
        }
    except NotImplementedError as error:
        return {
            "status": "unresolved",
            "message": "SymPy does not implement this valid operation.",
            "detail": str(error),
        }
    except Exception as error:  # worker boundary: always return a serializable state
        return {"status": "error", "message": f"Solver error: {error}"}
